#!/bin/sh
# Generate the gh:#1414 insertion decks in.pour_pack, in.pour_poly, in.pour_rate
# beside this script. The decks share the D/d = 6 container of in.pebble_bed;
# only the insertion fix differs. Frames are written with `run N pre no` so no
# set-up (re-sort, re-build, history reset) happens between frames: the run is
# one continuous run, like the Rust side.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
cd "$here"
gen() {
name=$1
cat > in.$name <<EOF
# gh:#1414 insertion cross-code deck (generated by make_pour_decks.sh; see
# crates/outram-park-fork-liggghts/verification_and_validation/insertion/README.md).
atom_style	granular
atom_modify	map array
boundary	f f f
newton		off
communicate	single vel yes
units		si
region		reg block -0.035 0.035 -0.035 0.035 -0.005 0.35 units box
create_box	1 reg
neighbor	0.003 bin
neigh_modify	delay 0
fix 		m1 all property/global youngsModulus peratomtype 5.0e6
fix 		m2 all property/global poissonsRatio peratomtype 0.3
fix 		m3 all property/global coefficientRestitution peratomtypepair 1 0.5
fix 		m4 all property/global coefficientFriction peratomtypepair 1 0.3
pair_style	gran model hertz tangential history
pair_coeff	* *
timestep	5e-6
fix		cyl all wall/gran model hertz tangential history primitive type 1 zcylinder 0.030 0. 0.
fix		zwall all wall/gran model hertz tangential history primitive type 1 zplane 0.0
EOF
cat >> in.$name
cat >> in.$name <<'EOF'
fix		grav all gravity 9.81 vector 0 0 -1
fix		integr all nve/sphere
thermo_style	custom step atoms ke
thermo		1000
thermo_modify	lost ignore norm no
EOF
prev=0
for s in 1 1000 1001 6001 10001 20000 24000 26000 30000; do
  d=$((s-prev))
  if [ $prev = 0 ]; then echo "run $d" >> in.$name; else echo "run $d pre no" >> in.$name; fi
  echo "write_dump all custom dump.F$s id x y z vx vy vz omegax omegay omegaz modify sort id" >> in.$name
  prev=$s
done
}
gen pour_pack <<'EOF'
region		ins cylinder z 0. 0. 0.028 0.05 0.32 units box
fix		pts all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.005
fix		pdd all particledistribution/discrete 15485867 1 pts 1.0
fix		ins all insert/pack seed 32452843 distributiontemplate pdd insert_every 1000 overlapcheck yes all_in yes vel constant 0. 0. -0.1 region ins particles_in_region 200
EOF
gen pour_poly <<'EOF'
region		ins cylinder z 0. 0. 0.028 0.05 0.32 units box
fix		pts1 all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.005
fix		pts2 all particletemplate/sphere 49979687 atom_type 1 density constant 2500 radius constant 0.0035
fix		pdd all particledistribution/discrete 15485867 2 pts1 0.7 pts2 0.3
fix		ins all insert/pack seed 32452843 distributiontemplate pdd insert_every 1000 overlapcheck yes all_in yes vel uniform 0. 0. -0.1 0.02 0.02 0.02 region ins volumefraction_region 0.2
EOF
gen pour_rate <<'EOF'
region		ins cylinder z 0. 0. 0.028 0.05 0.32 units box
fix		pts all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.005
fix		pdd all particledistribution/discrete 15485867 1 pts 1.0
fix		ins all insert/rate/region seed 32452843 distributiontemplate pdd insert_every 1000 overlapcheck yes all_in yes vel constant 0. 0. -0.1 nparticles 120 particlerate 8000 region ins
EOF
gen pour_block <<'EOF'
region		ins block -0.016 0.016 -0.016 0.016 0.05 0.3 units box
fix		pts all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.004
fix		pdd all particledistribution/discrete/numberbased 15485867 1 pts 1.0
fix		ins all insert/pack seed 32452843 distributiontemplate pdd insert_every 1000 overlapcheck yes all_in no random_distribute uncorrelated vel gaussian 0. 0. -0.1 0.03 0.03 0.03 omega constant 1. 2. 3. region ins mass_in_region 0.1
EOF
gen pour_nocheck <<'EOF'
region		ins cylinder z 0. 0. 0.028 0.05 0.32 units box
fix		pts all particletemplate/sphere 15485863 atom_type 1 density constant 2500 radius constant 0.005
fix		pdd all particledistribution/discrete 15485867 1 pts 1.0
fix		ins all insert/pack seed 32452843 distributiontemplate pdd insert_every 1000 overlapcheck no all_in yes vel constant 0. 0. -0.1 region ins particles_in_region 6
EOF
